/** Synthetic controls for capture tests, not a consultant-quality benchmark. No external requests. */
import http from 'node:http';
export function markup(kind,broken=false){
 const landing=kind==='landing';
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${landing?'Field Notes — sample launch':'Workspace preferences'}</title><meta name="description" content="Synthetic visual evidence fixture"><style>
 *{box-sizing:border-box}body{margin:0;background:#f5f4ef;color:#142c2a;font:18px/1.6 system-ui}a{color:inherit}a:focus-visible,button:focus-visible,input:focus-visible{outline:4px solid #075d48;outline-offset:5px}.skip{position:absolute;left:-10000px}.skip:focus{left:20px;top:10px;background:white}header{border-bottom:1px solid #afbab4;padding:24px 6vw;display:flex;justify-content:space-between;gap:24px}main{max-width:1000px;margin:auto;padding:64px 6vw 120px;${broken?'width:1100px;max-width:none;':''}}h1{font-size:clamp(36px,7vw,76px);line-height:1.05;max-width:12ch}p{max-width:60ch}button{padding:16px 24px;border:2px solid #142c2a;background:#142c2a;color:white;font:inherit;min-height:48px}button:hover{background:#275b50;transform:translateY(-2px)}.panel{background:white;border:1px solid #afbab4;padding:24px;margin:32px 0}.row{padding:20px 0;border-bottom:1px solid #ddd;display:flex;justify-content:space-between;gap:20px}input{width:24px;height:24px}footer{padding:24px 6vw;background:#142c2a;color:white}.marker{display:inline-block;width:32px;height:32px;background:#ca4d31;animation:turn 3s linear infinite}@keyframes turn{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}@media(max-width:500px){main{padding:32px 20px}header{padding:20px}.row{display:block}}
 </style></head><body><a class="skip" href="#main">Skip to content</a><header><strong>${landing?'Field Notes':'Workspace'}</strong><nav aria-label="Main"><a href="/${landing?'app':'landing'}">${landing?'Preferences':'Launch page'}</a></nav></header><main id="main">
 ${landing?'<span class="marker" aria-hidden="true"></span><h1>Make room for a clear thought.</h1><p>A synthetic notebook launch page for testing responsive captures. No product or performance claim is real.</p>':'<h1>Preferences</h1><p>Choose what this sample workspace shows. These controls do not save to a service.</p>'}
 <section class="panel"><h2>${landing?'A page for each idea':'Notifications'}</h2><p>${landing?'Read, revise and keep only what matters. This fixture has real text and an explicit mobile layout.':'Use the keyboard to reach each control. Focus must remain visible.'}</p>${landing?'': '<div class="row"><label for="email">Email updates</label><input id="email" type="checkbox" checked></div><div class="row"><label for="digest">Weekly digest</label><input id="digest" type="checkbox"></div>'}<button type="button">${broken?'':'Try the sample'}</button></section>
 <section class="panel"><h2>Details</h2><p>Longer content tests the second viewport. No picture of a client, private information or external font is used.</p><p>Keyboard, hover and reduced-motion views are separate evidence, not acceptance tests.</p></section></main><footer>Illustrative fixture only.</footer></body></html>`;
}
export async function serve(){
 const server=http.createServer((req,res)=>{const u=new URL(req.url,'http://localhost');if(!['/landing','/app'].includes(u.pathname)){res.writeHead(404);return res.end('Missing');}res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'});res.end(markup(u.pathname.slice(1),u.searchParams.has('broken')));});
 await new Promise(r=>server.listen(0,'127.0.0.1',r));return server;
}
